import Foundation
import XCTest

@testable import Vocal

final class ArtifactNativeValidationTests: XCTestCase {
  func testSyntheticMP3DecodesButInvalidContainersDoNot() async throws {
    let root = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
    try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
    defer { try? FileManager.default.removeItem(at: root) }
    let file = root.appendingPathComponent("output.mp3")
    // Synthetic 150ms silence, encoded once for this fixture. No runtime encoder dependency.
    let encoded =
      ""
    let valid = try XCTUnwrap(Data(base64Encoded: encoded))
    try valid.write(to: file)
    try await validateMP3Artifact(file)
    for invalid in [
      Data(), Data("<html>Forbidden</html>".utf8), Data(valid.prefix(12)), wavFixture(),
    ] {
      try invalid.write(to: file)
      do {
        try await validateMP3Artifact(file)
        XCTFail("Expected actual MP3 validation to reject invalid content")
      } catch {
        XCTAssertEqual(error as? JobArtifactFailure, .invalidOutput)
      }
    }
  }

  private func wavFixture() -> Data {
    // Valid mono PCM WAV, intentionally named .mp3 by the test.
    var data = Data("RIFF".utf8)
    func append<T: FixedWidthInteger>(_ value: T) {
      var little = value.littleEndian
      withUnsafeBytes(of: &little) { data.append(contentsOf: $0) }
    }
    append(UInt32(236))
    data.append(Data("WAVEfmt ".utf8))
    append(UInt32(16))
    append(UInt16(1))
    append(UInt16(1))
    append(UInt32(8000))
    append(UInt32(16000))
    append(UInt16(2))
    append(UInt16(16))
    data.append(Data("data".utf8))
    append(UInt32(200))
    data.append(Data(repeating: 0, count: 200))
    return data
  }
}
